const test=require('node:test'),assert=require('node:assert/strict');
test('Health and affinity overlays render actual actors, remain off by default, and clean up removed views',async()=>{const T=await import('../vendor/three.module.js'),{createOutbreakView}=await import('../outbreak-view.mjs'),{world}=await require('./outbreak-fixture.cjs')('brooms');const previous=global.document;global.document={createElement:()=>({width:0,height:0,getContext:()=>({clearRect(){},fillRect(){},fillText(){}})})};try{const scene=new T.Scene(),view=createOutbreakView(scene,.1);view.draw(world,()=>0);const root=scene.children[0];assert.equal(root.children.length,6);assert(root.children.every(g=>!g.children.find(o=>o.isSprite).visible));assert.doesNotThrow(()=>view.draw(world,()=>0,{admin:true,colorKind:'regional'}));assert(root.children.every(g=>g.children.find(o=>o.isSprite).visible));const id=Object.keys(world.actors)[0];world.entities[id].active=false;view.draw(world,()=>0,{admin:true,colorKind:'national'});assert.equal(root.children.length,5);}finally{global.document=previous;}});
test('rendering during a tile drag does not reveal duplicate live actors or mutate simulation',async()=>{const T=await import('../vendor/three.module.js'),{createOutbreakView}=await import('../outbreak-view.mjs'),{world}=await require('./outbreak-fixture.cjs')('brooms');const previous=global.document;global.document={createElement:()=>({width:0,height:0,getContext:()=>({clearRect(){},fillRect(){},fillText(){}})})};try{const scene=new T.Scene(),view=createOutbreakView(scene,.1),saved=JSON.stringify(world);view.draw(world,()=>0);const root=scene.children[0],position=root.children[0].position,capture=view.captureDrag({origin:{x:0,z:0},centers:[position],radius:1});assert(capture.group.children.length>0);view.draw(world,()=>0);assert(root.children.filter(g=>g.userData.dragHidden).every(g=>!g.visible));capture.release();view.draw(world,()=>0);assert(root.children.every(g=>g.visible));assert.equal(JSON.stringify(world),saved);}finally{global.document=previous;}});

test('Large populations use shared instanced meshes, actual HP bars and reversible drag hiding',async()=>{const T=await import('../vendor/three.module.js'),{createOutbreakView}=await import('../outbreak-view.mjs'),{spawnActors}=await import('../outbreak-simulation.mjs');let {world,board,graph}=await require('./outbreak-fixture.cjs')('brooms');for(const i of board.instances)for(let n=0;n<3;n++)world=spawnActors(world,board,graph,i.instanceId,32);const scene=new T.Scene(),view=createOutbreakView(scene,.1);view.draw(world,()=>0,{admin:true});const crowd=scene.children[1],meshes=crowd.children.filter(m=>m.isInstancedMesh);assert(meshes.length>1&&meshes.length<20);assert.equal(scene.children[0].visible,false);assert.equal(meshes[0].count,198);const saved=JSON.stringify(world),capture=view.captureDrag({origin:{x:0,z:0},centers:Object.values(world.actors).map(a=>a.position),radius:1});assert.equal(capture.group.children.length,198);view.draw(world,()=>0,{admin:true});assert(meshes.every(m=>m.count===0));capture.release();view.draw(world,()=>0,{admin:true});assert.equal(meshes[0].count,198);assert.equal(JSON.stringify(world),saved);});
